fn ones_like<T>(a: &Vec<T>) -> Vec<i32> {
    let n = a.len();
    let mut result = Vec::with_capacity(n);

    let mut i = 0usize;
    while i < n {
        // At this point:
        // 0 <= i <= n
        // result.len() == i
        // all elements in result are 1
        result.push(1);
        i += 1;
        // The number of remaining iterations is n - i, which decreases in each step,
        // ensuring loop termination.
    }

    // After the loop:
    // result.len() == n
    // every element in result is 1
    result
}